/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 04.03.25
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "_child">CustAccount</param>
/// <param name = "_firma">NDXCompanyBE</param>
/// <param name = "_alliance">CustAccount</param>
/// <param name = "_partyId">RefRecId</param>
/// <param name = "_forUpdate">boolean (false)</param>
/// <param name = "_pessimisticLock">boolean (false)</param>
/// <returns>NDXTmpKumUmsCust</returns>
static NDXTmpKumUmsCust find(
    NDXUmsSignature _umsSignature,
    NDXMonthYearSignature _monthYearSignature,
    CustAccount _child,
    NDXCompanyBE _firma,
    CustAccount _alliance,
    RefRecId _partyId,
    boolean _forUpdate = false,
    boolean _pessimisticLock = false)
{
    NDXTmpKumUmsCust nDXTmpKumUmsCust;
    RefRecId party = _partyId;

    if (!party)
    {
        if (_firma == NDXCompanyBE::WithoutAssignment ||
            _firma == NDXCompanyBE::AllCompanies)
        {
            party = CustTable::NDXfindCustByFirma(_alliance, NDXCompanyBE::Niedax).Party;
        }
        else
        {
            party = CustTable::NDXfindCustByFirma(_alliance, _firma).Party;
        }
    }
    nDXTmpKumUmsCust.selectForUpdate(_forUpdate);
    if (_pessimisticLock)
    {
        nDXTmpKumUmsCust.concurrencyModel(ConcurrencyModel::Pessimistic);
    }

    if (_child)
    {
        select firstonly nDXTmpKumUmsCust
                where nDXTmpKumUmsCust.UmsSignature == _umsSignature
                && nDXTmpKumUmsCust.MonthYearSignature == _monthYearSignature
                && nDXTmpKumUmsCust.Child == _child
                && nDXTmpKumUmsCust.Company == _firma
                && nDXTmpKumUmsCust.Alliance == _alliance;

        if (party)
        {
            if (!nDXTmpKumUmsCust)
            {
                select firstonly nDXTmpKumUmsCust
                    where nDXTmpKumUmsCust.UmsSignature == _umsSignature
                    && nDXTmpKumUmsCust.MonthYearSignature == _monthYearSignature
                    && nDXTmpKumUmsCust.Child == _child
                    && nDXTmpKumUmsCust.Company == _firma
                    && nDXTmpKumUmsCust.Party == party;
            }
            else
            {
                if (!nDXTmpKumUmsCust.Party)
                {
                    nDXTmpKumUmsCust.Party = party;
                }
            }
        }
        else
        {
            select nDXTmpKumUmsCust
                where nDXTmpKumUmsCust.UmsSignature == _umsSignature         
                && nDXTmpKumUmsCust.MonthYearSignature == _monthYearSignature   
                && nDXTmpKumUmsCust.Child == _child                
                && nDXTmpKumUmsCust.Company == _firma 
                && nDXTmpKumUmsCust.Alliance == _alliance;
        }
    }
    return nDXTmpKumUmsCust;
}

/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 04.03.25
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_monthYearSignature">NDXMonthYearSignature</param>
/// <param name = "_child">CustAccount</param>
/// <param name = "_firma">NDXCompanyBE</param>
/// <param name = "_salesGroupId">CommissSalesGroup</param>
/// <param name = "_forUpdate">boolean (false)</param>
/// <param name = "_pessimisticLock">boolean (false)</param>
/// <returns>NDXTmpKumUmsCust</returns>
static NDXTmpKumUmsCust findSalesGroup(
    NDXUmsSignature _umsSignature,
    NDXMonthYearSignature _monthYearSignature,
    CustAccount _child,
    NDXCompanyBE _firma,
    CommissSalesGroup _salesGroupId,
    boolean _forUpdate = false,
    boolean _pessimisticLock = false)
{
    NDXTmpKumUmsCust nDXTmpKumUmsCust;
    nDXTmpKumUmsCust.selectForUpdate(_forUpdate);
    if (_pessimisticLock)
    {
        nDXTmpKumUmsCust.concurrencyModel(ConcurrencyModel::Pessimistic);
    }

    if (_salesGroupId && _child)
    {
        select nDXTmpKumUmsCust
            where   nDXTmpKumUmsCust.UmsSignature         == _umsSignature &&
                    nDXTmpKumUmsCust.MonthYearSignature   == _monthYearSignature &&
                    nDXTmpKumUmsCust.Child                == _child &&
                    nDXTmpKumUmsCust.Company              == _firma &&
                    nDXTmpKumUmsCust.SalesGroup           == _salesGroupId;
    }

    return nDXTmpKumUmsCust;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "_umsSignature">NDXUmsSignature</param>
/// <param name = "_alliance">CustAccount</param>
static void deleteRecords(NDXUmsSignature _umsSignature, CustAccount _alliance)
{
    NDXTmpKumUmsCust          table;
    ;

    table.skipDataMethods(true);
    table.skipAosValidation(true);
    table.skipDatabaseLog(true);
    table.skipEvents(true);
    table.skipDeleteActions(true);

    if (_alliance)
    {
        delete_from     table
                where       table.UmsSignature == _umsSignature &&
                            table.Alliance     == _alliance;
    }
    else
    {
        delete_from     table
                where       table.UmsSignature == _umsSignature;
    }
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "_copyTo">NDXUmsSignature</param>
/// <param name = "_copyToOld">NDXUmsSignature</param>
/// <param name = "_sic">boolean</param>
/// <param name = "_copyFromSic">NDXUmsSignature</param>
/// <param name = "_only4Alliance">CustAccount</param>
static void updateRecords(NDXUmsSignature _copyTo,NDXUmsSignature _copyToOld, boolean _sic, NDXUmsSignature _copyFromSic, CustAccount _only4Alliance)
{

    // bestehende Daten sichern
    NDXTmpKumUmsCust      table;
    Common                      commonCopySic;
    int64                       anzBefore, anzAfter;
    DictTable                   dictTable;

    NDXUmsSignature         l_copyFrom2 = _copyTo;
    NDXUmsSignature         l_copyTo2   = _copyToOld;        
    boolean                 l_lSic      = _sic;

    //BP deviation documented
    table.skipDataMethods(true);
    table.skipAosValidation(true);
    table.skipDatabaseLog(true);
    table.skipEvents(true);
    table.skipDeleteActions(true);

    // Sicherung der CopyFrom-Daten
    if (l_lSic)
    {
        dictTable       = new DictTable(table.TableId);
        commonCopySic   = dictTable.makeRecord();
        ttsbegin;

        // alte Sicherung löschen
        if (_only4Alliance)
        {
            delete_from     table
                where       table.UmsSignature == _copyFromSic &&
                            table.Alliance     == _only4Alliance;
        }
        else
        {
            delete_from     table
                where       table.UmsSignature == _copyFromSic;
        }

        // aktuelle Daten sichern
        if (_only4Alliance)
        {
            while select table
                where    table.UmsSignature    == l_copyFrom2      &&
                            table.Alliance        == _only4Alliance
            {
                buf2Buf(table, commonCopySic);
                commonCopySic.(dictTable.fieldname2id(identifierstr(UmsSignature))) = _copyFromSic;
                commonCopySic.doInsert();
            }
        }
        else
        {
            while select table
                where    table.UmsSignature == l_copyFrom2
            {
                buf2Buf(table, commonCopySic);
                commonCopySic.(dictTable.fieldname2id(identifierstr(UmsSignature))) = _copyFromSic;
                commonCopySic.doInsert();
            }
        }
        ttscommit;
    }

    if (_only4Alliance)
    {
        anzBefore = (select     count(recid)
                        from    NDXTmpKumUmsCust
                        where   NDXTmpKumUmsCust.UmsSignature == l_copyTo2 &&
                                NDXTmpKumUmsCust.Alliance     == _only4Alliance).recid;

        update_recordset        table
            setting             UmsSignature = l_copyTo2
            where               table.UmsSignature == l_copyFrom2 &&
                                table.Alliance     == _only4Alliance;

        anzAfter  = (select     count(recid)
                        from    NDXTmpKumUmsCust
                        where   NDXTmpKumUmsCust.UmsSignature == l_copyTo2 &&
                                NDXTmpKumUmsCust.Alliance     == _only4Alliance).recid;
    }
    else
    {
        anzBefore = (select     count(recid)
                        from    NDXTmpKumUmsCust
                        where   NDXTmpKumUmsCust.UmsSignature == l_copyTo2).recid;

        update_recordset        table
            setting             UmsSignature = l_copyTo2
            where               table.UmsSignature == l_copyFrom2;

        anzAfter  = (select     count(recid)
                        from    NDXTmpKumUmsCust
                        where   NDXTmpKumUmsCust.UmsSignature == l_copyTo2).recid;
    }
    if (_copyToOld)
    {
        info(strfmt("@NDX:NDXRecordsSavedIn", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), anzAfter - anzBefore, tableId2Name(table.TableId), l_copyTo2));       // [%1] [%2] Records in [%3] unter [%4] gesichert
    }
    else
    {
        info(strfmt("@NDX:NDXRecordsTransferedTo", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())), anzAfter - anzBefore, tableId2Name(table.TableId), l_copyTo2));       // [%1] [%2] Records in [%3] unter [%4] übertragen
    }


}

/// <summary>
/// PaffH 01.03.25
