{
    try
    {
        super();
    }
    catch
    {
        throw error(strFmt("@NDX:NDXTmpKumUmsCustInsertError",
            tableId2Name(this.TableId), '', this.UmsSignature, this.MonthYearSignature, this.Child, this.Company, this.Alliance));
    }
}
